window.CIRCUIT_GUIDES = {"1.1": {"family": "resistor", "title": "From a real system to a circuit model", "steps": [{"title": "Follow the complete path", "text": "Start at the voltage source, follow the wire through the resistor, and return to the source. A sustained current needs a closed path.", "audio": "audio/guided-5b726a78920b79.mp3"}, {"title": "Separate source and load", "text": "The source transfers energy to the circuit. The resistor absorbs electrical energy. Wires are treated as ideal connections in this example.", "audio": "audio/guided-64c3e8d5aa6090.mp3"}, {"title": "Try a concrete model", "text": "Our example has a six ohm load. Divide the displayed supply voltage by six to find current. Increase the supply with the slider and watch current increase.", "audio": "audio/guided-777c2c2ed6db15.mp3"}, {"title": "Check the model, not just the drawing", "text": "The symbols are an ideal model of a physical system. The diagram tells you which terminals are connected; its geometric shape does not determine the current.", "audio": "audio/guided-1c3500ad3a1ad3.mp3"}], "check": {"question": "In this model, what absorbs energy?", "options": ["The resistor", "An ideal connecting wire", "The current arrow"], "answer": 0, "why": "The resistor absorbs power. Ideal connecting wires have zero resistance in this model."}}, "1.2": {"family": "resistor", "title": "Connect voltage, current, and power", "steps": [{"title": "Name the quantities", "text": "Voltage is an energy difference per unit charge. Current is a rate of charge flow. Use volts, amperes, and ohms consistently.", "audio": "audio/guided-0a1848d0f6dcdc.mp3"}, {"title": "Use a reference direction", "text": "The current arrow enters the marked positive terminal of the resistor. This is the passive sign convention.", "audio": "audio/guided-873346b6d4d6cc.mp3"}, {"title": "Calculate the example", "text": "For the six ohm resistor, current equals voltage divided by six. Absorbed power is voltage times current, which is also current squared times resistance.", "audio": "audio/guided-5a53c593d34d7b.mp3"}, {"title": "Check energy and units", "text": "A positive resistor always absorbs nonnegative power. Volts times amperes gives watts. Change the supply and see that doubling voltage quadruples resistor power.", "audio": "audio/guided-ca46af38c56360.mp3"}], "check": {"question": "If voltage doubles across the same positive resistance, power becomes…", "options": ["Four times as large", "Twice as large", "Half as large"], "answer": 0, "why": "P = V²/R. Squaring twice the voltage gives four times the power."}}, "1.3": {"family": "conditions", "title": "Open, loaded, and short circuit", "steps": [{"title": "Observe the load", "text": "With a finite resistor connected, the source supplies a finite current. This is the ordinary loaded operating condition.", "audio": "audio/guided-f3037eb0c3fb0b.mp3"}, {"title": "Open the path", "text": "An open circuit breaks the conducting path. Current is zero, even though a voltage can remain across the open terminals.", "audio": "audio/guided-e1e57c8bc51c76.mp3"}, {"title": "Short the terminals", "text": "A short connects the terminals with zero ideal resistance. The short voltage is zero. An ideal voltage source shorted directly has no finite current solution.", "audio": "audio/guided-aa5c87eb576082.mp3"}, {"title": "Use a physical model when necessary", "text": "Real sources have internal resistance and protection. Those features limit short circuit current. Do not divide by zero and present a finite answer.", "audio": "audio/guided-59be0d76fc0f98.mp3"}], "check": {"question": "For an ideal open circuit, which statement is true?", "options": ["Current is zero; voltage may be nonzero", "Voltage and current must both be zero", "Current must be infinite"], "answer": 0, "why": "The open path carries no current. Its terminal voltage depends on the rest of the circuit."}}, "1.4": {"family": "resistor", "title": "Reference directions are a choice", "steps": [{"title": "Choose a ground", "text": "Pick one node as zero volts. Other node voltages are measured relative to it. Changing the reference does not change physical voltage differences.", "audio": "audio/guided-3868e9eede01e2.mp3"}, {"title": "Mark polarity and current", "text": "The resistor voltage is positive at the terminal where the chosen current enters. Ohm’s law is then voltage equals resistance times current.", "audio": "audio/guided-de342b689bfd12.mp3"}, {"title": "Interpret the sign", "text": "If a solved current is negative, the actual current flows opposite to the arrow. The circuit is not automatically wrong.", "audio": "audio/guided-bad12d2665da42.mp3"}, {"title": "Keep the convention consistent", "text": "Reversing a voltage reference changes the sign of that voltage. Reversing both voltage and current references leaves their power product unchanged.", "audio": "audio/guided-6f79d3b9527ddd.mp3"}], "check": {"question": "A computed current is negative. What does that tell you?", "options": ["It flows opposite to the chosen reference", "The source has failed", "The resistance must be negative"], "answer": 0, "why": "The sign describes direction relative to your arrow, not whether current is physically possible."}}, "1.5": {"family": "elements", "title": "Resistors, capacitors, and inductors", "steps": [{"title": "Start with resistance", "text": "For a resistor under passive references, voltage equals resistance times current. A positive resistor dissipates energy.", "audio": "audio/guided-51e21c253bc36e.mp3"}, {"title": "Add a capacitor", "text": "Capacitor current is capacitance times the rate of change of voltage. A constant capacitor voltage gives zero capacitor current.", "audio": "audio/guided-879f51c18d97f4.mp3"}, {"title": "Add an inductor", "text": "Inductor voltage is inductance times the rate of change of current. A constant inductor current gives zero inductor voltage.", "audio": "audio/guided-7176da452d1b05.mp3"}, {"title": "Separate storage from dissipation", "text": "A capacitor stores one half C V squared. An inductor stores one half L I squared. Ideal storage elements can return energy; an ideal resistor cannot.", "audio": "audio/guided-e08527defdb751.mp3"}], "check": {"question": "Which quantity is continuous through an ordinary ideal switching event without an impulse?", "options": ["Capacitor voltage", "Capacitor current", "Resistor current"], "answer": 0, "why": "Finite current cannot change capacitor voltage instantaneously. Inductor current has the analogous continuity property."}}, "1.6": {"family": "transform", "title": "Transform a source at its terminals", "steps": [{"title": "Identify the two terminals", "text": "A voltage source in series with a resistor defines a two terminal port. Source transformation preserves the external voltage and current relationship.", "audio": "audio/guided-52be6e29f6e123.mp3"}, {"title": "Compute the Norton current", "text": "Replace the series voltage source and resistance with a current source in parallel with the same resistance. The source current equals source voltage divided by resistance.", "audio": "audio/guided-ccd98664b96e1c.mp3"}, {"title": "Check the example", "text": "In this example resistance is six ohms. The displayed supply divided by six gives the equivalent current source value. Open circuit voltage is unchanged.", "audio": "audio/guided-f4ef7159461b84.mp3"}, {"title": "Respect the boundary", "text": "The two circuits are equivalent at their external terminals. Internal currents and internal power values do not all remain the same. Controlled sources require their constraints to be preserved.", "audio": "audio/guided-914718837eabd6.mp3"}], "check": {"question": "What is preserved by a valid source transformation?", "options": ["The external terminal relationship", "Every internal branch current", "The position of every component"], "answer": 0, "why": "The connected load sees the same terminal voltage-current relation, not identical internal behavior."}}, "1.7": {"family": "loop", "title": "Use both Kirchhoff laws", "steps": [{"title": "Read the loop", "text": "A voltage source drives two series resistors: two ohms and four ohms. The same current flows through each resistor.", "audio": "audio/guided-823a0cd13839a1.mp3"}, {"title": "Write the voltage balance", "text": "Around the loop, the source rise equals the sum of resistor drops. The equation is supply voltage minus two I minus four I equals zero.", "audio": "audio/guided-d008895410c289.mp3"}, {"title": "Solve and check", "text": "The total resistance is six ohms. Divide supply voltage by six. Multiply that current by each resistance to find the two voltage drops.", "audio": "audio/guided-0dd1e1e828f0bc.mp3"}, {"title": "Bring in the node rule", "text": "At a junction, total incoming current equals total outgoing current. Kirchhoff’s current law expresses charge conservation; the voltage law expresses the loop potential balance in this lumped model.", "audio": "audio/guided-294948d02cc755.mp3"}], "check": {"question": "At the default 12 V supply, the 4 Ω resistor drops…", "options": ["8 V", "4 V", "12 V"], "answer": 0, "why": "I = 12/(2+4) = 2 A, so the four ohm drop is 8 V."}}, "1.8": {"family": "parallel", "title": "Solve branches with node and loop equations", "steps": [{"title": "Label the unknown currents", "text": "This example has a six ohm branch and a three ohm branch in parallel. Label each branch current downward from the common top node.", "audio": "audio/guided-04a87c09e1e384.mp3"}, {"title": "Use the shared voltage", "text": "Both branches connect to the same pair of nodes, so both have the source voltage. Their currents do not need to be equal.", "audio": "audio/guided-cb57b48ea6c93f.mp3"}, {"title": "Calculate and add", "text": "Divide source voltage by six for the first branch and by three for the second. Add those currents to get the source current.", "audio": "audio/guided-9013d87abda110.mp3"}, {"title": "Check Kirchhoff’s current law", "text": "The source current must equal the sum of the two branch currents. In more complex networks, use independent loop equations with the node equations and solve the unknowns together.", "audio": "audio/guided-815d08f8cfa1f0.mp3"}], "check": {"question": "Which branch has the greater current in this example?", "options": ["The 3 Ω branch", "The 6 Ω branch", "They are equal"], "answer": 0, "why": "Both branches have the same voltage. The smaller resistance carries the larger current."}}, "1.9": {"family": "superposition", "title": "One independent source at a time", "steps": [{"title": "Identify a linear circuit", "text": "Superposition applies to linear voltages and currents. Here two independent voltage sources oppose each other through a six ohm resistance.", "audio": "audio/guided-7269f8e0a14a91.mp3"}, {"title": "Keep the first source", "text": "Set the other independent voltage source to zero, which replaces it by a short. Keep all resistances and any controlled sources.", "audio": "audio/guided-91d3c88c7c2c24.mp3"}, {"title": "Add signed contributions", "text": "For this illustrative loop, the fixed second source is six volts and opposes the adjustable source. The total current is the adjustable voltage minus six, divided by six.", "audio": "audio/guided-609ab6144c1bfc.mp3"}, {"title": "Do not add powers", "text": "Add the current or voltage contributions first. Then calculate power from the total. Power itself is nonlinear, so individual source powers cannot simply be superposed.", "audio": "audio/guided-254a5ad959bfac.mp3"}], "check": {"question": "When an independent ideal current source is set to zero, replace it by…", "options": ["An open circuit", "A short circuit", "A 1 Ω resistor"], "answer": 0, "why": "Zero current means an open branch. A zero voltage source instead becomes a short circuit."}}, "1.10": {"family": "thevenin", "title": "Replace a network seen by one load", "steps": [{"title": "Separate the load port", "text": "Remove the load and mark its two terminals. The rest of a linear network can often be replaced by a Thévenin voltage and resistance.", "audio": "audio/guided-51a8c17642e275.mp3"}, {"title": "Find the two quantities", "text": "The Thévenin voltage is the open circuit voltage. Find the Thévenin resistance with independent sources zeroed, or use a test source when needed for controlled sources.", "audio": "audio/guided-8f78a8658f9c61.mp3"}, {"title": "Reconnect the example load", "text": "This example has a Thévenin resistance of two ohms and a four ohm load. Load current equals the displayed Thévenin voltage divided by six ohms.", "audio": "audio/guided-94d00048fc4cf7.mp3"}, {"title": "Check the load result", "text": "Multiply load current by four ohms to get load voltage. Do not confuse open circuit voltage with loaded voltage. Keep the port polarity consistent.", "audio": "audio/guided-de7215396830df.mp3"}], "check": {"question": "At the default 12 V Thévenin voltage, the 4 Ω load voltage is…", "options": ["8 V", "12 V", "2 V"], "answer": 0, "why": "I = 12/(2+4) = 2 A. The load voltage is 2 × 4 = 8 V."}}, "2.1": {"family": "rc", "title": "See what changes after switching", "steps": [{"title": "Separate three moments", "text": "Distinguish the circuit before switching, immediately after switching, and long after switching. Those are different questions.", "audio": "audio/guided-c1b1689fb6dbc6.mp3"}, {"title": "Track the stored energy", "text": "In this charging example the capacitor starts at zero volts. A ten volt source drives a two kiloohm resistor and a one hundred microfarad capacitor.", "audio": "audio/guided-7072b3d051df62.mp3"}, {"title": "Watch the response", "text": "The time constant is zero point two seconds. Move the time slider to see the voltage approach ten volts exponentially, rather than jumping there immediately.", "audio": "audio/guided-0cdbb34a1ca43c.mp3"}, {"title": "Check both limits", "text": "At zero time the capacitor retains its initial voltage. At a long time the current approaches zero and the capacitor voltage approaches the source value.", "audio": "audio/guided-86f4aca517c7a3.mp3"}], "check": {"question": "After one time constant, a zero-start RC charge reaches approximately…", "options": ["63.2% of the final voltage", "100% of the final voltage", "36.8% of the final voltage"], "answer": 0, "why": "The charged fraction is 1 − e⁻¹, approximately 0.632. The remaining difference is about 36.8%."}}, "2.2": {"family": "continuity", "title": "Apply the switching law correctly", "steps": [{"title": "Find the value before the switch", "text": "For this example, the capacitor is already charged to three volts immediately before switching. That initial value comes from the pre-switch circuit.", "audio": "audio/guided-d9afd665b279b8.mp3"}, {"title": "Carry the state across the instant", "text": "With no impulsive current, capacitor voltage immediately after the switch is still three volts. Inductor current has the corresponding continuity rule when there is no impulsive voltage.", "audio": "audio/guided-bd55d2f6b0b917.mp3"}, {"title": "Let the new circuit set the future", "text": "The new circuit drives the capacitor toward ten volts through two kiloohms. With one hundred microfarads, the time constant is zero point two seconds.", "audio": "audio/guided-a1b26032e490f5.mp3"}, {"title": "Do not freeze the whole response", "text": "Continuity applies across the switching instant. It does not mean the capacitor voltage stays constant forever. Capacitor current and inductor voltage may jump.", "audio": "audio/guided-507c8fbb282930.mp3"}], "check": {"question": "In this example, uC(0⁺) equals…", "options": ["3 V", "10 V", "0 V"], "answer": 0, "why": "The finite-current switching event preserves the initial 3 V capacitor voltage."}}, "2.3": {"family": "three", "title": "Build a first order response from three values", "steps": [{"title": "Find the initial value", "text": "This illustrative capacitor starts at two volts. Determine the initial state from the pre-switch circuit and continuity.", "audio": "audio/guided-f09132bb0be267.mp3"}, {"title": "Find the final value", "text": "For the new DC steady state, the capacitor is open circuit. In this example its voltage tends toward ten volts.", "audio": "audio/guided-db5219054c7845.mp3"}, {"title": "Find the time constant", "text": "Look into the post-switch circuit from the storage element with independent sources zeroed. Here resistance is two kiloohms and capacitance is one hundred microfarads, giving zero point two seconds.", "audio": "audio/guided-f5d5be15f03326.mp3"}, {"title": "Assemble and verify", "text": "Use final value plus initial minus final, times the exponential of negative time divided by the time constant. Check that substituting zero and infinite time returns the two required limits.", "audio": "audio/guided-c8025af471b415.mp3"}], "check": {"question": "Which expression has the correct limits for this example?", "options": ["10 − 8e^(−t/0.2) V", "2 + 10e^(−t/0.2) V", "10 + 8e^(−t/0.2) V"], "answer": 0, "why": "At t=0 it gives 2 V; as t tends to infinity it gives 10 V."}}, "2.4": {"family": "rc", "title": "Read the RC charge and its current", "steps": [{"title": "Identify the storage voltage", "text": "The capacitor begins uncharged. The resistor limits the charging current from the ten volt source.", "audio": "audio/guided-ced213337e5513.mp3"}, {"title": "Write voltage and current", "text": "Capacitor voltage is ten times one minus the exponential. Current is five milliamperes times the same decaying exponential, with a time constant of zero point two seconds.", "audio": "audio/guided-e0dda3bef33d17.mp3"}, {"title": "Move through physical time", "text": "Move the slider. As capacitor voltage rises, the resistor voltage falls. The charging current therefore falls too.", "audio": "audio/guided-aa5c3eb8d951dc.mp3"}, {"title": "Check the steady state", "text": "At a long time the capacitor voltage is ten volts, the resistor drop is zero, and current is zero. A capacitor is not an open circuit during the entire transient.", "audio": "audio/guided-e28cac24654a3c.mp3"}], "check": {"question": "During this RC charging process, the current…", "options": ["Decreases toward zero", "Increases toward infinity", "Stays at 5 mA forever"], "answer": 0, "why": "The resistor voltage decreases as the capacitor charges, so current decays exponentially."}}, "2.5": {"family": "rl", "title": "Watch an inductor discharge", "steps": [{"title": "Keep the initial current", "text": "In this separate illustrative example, a one henry inductor initially carries two amperes. It discharges through two ohms after the source is disconnected.", "audio": "audio/guided-82ccd3ff6ddb22.mp3"}, {"title": "Find the decay rate", "text": "The time constant is inductance divided by resistance, so it is zero point five seconds. Current is two times the exponential of negative time divided by zero point five.", "audio": "audio/guided-10532633c7e67c.mp3"}, {"title": "Understand the voltage sign", "text": "Choose the passive inductor voltage reference where current enters. Because current is decreasing, inductance times its derivative is negative. The inductor returns stored energy.", "audio": "audio/guided-f89d5865df0cad.mp3"}, {"title": "Check the energy", "text": "Initial stored energy is two joules. At long time both current and stored energy approach zero. The resistor absorbs the released energy in this ideal discharge model.", "audio": "audio/guided-060259e8f942c9.mp3"}], "check": {"question": "At one time constant, the 2 A initial current is approximately…", "options": ["0.736 A", "1.264 A", "2 A"], "answer": 0, "why": "i(τ) = 2e⁻¹ ≈ 0.736 A. This is a decay, not a charge-up fraction."}}, "3.1": {"family": "sine", "title": "Read the sinusoidal quantities", "steps": [{"title": "Separate peak from RMS", "text": "This example voltage has a peak magnitude of ten volts. Its RMS value is ten divided by the square root of two, about seven point zero seven volts.", "audio": "audio/guided-585f17500057b6.mp3"}, {"title": "Read the time scale", "text": "Frequency is fifty hertz, so the period is twenty milliseconds. Angular frequency is two pi times fifty radians per second.", "audio": "audio/guided-b7329bbf2b6c19.mp3"}, {"title": "Change phase without changing magnitude", "text": "The slider changes the phase angle. Watch the waveform shift while its amplitude and RMS value stay unchanged.", "audio": "audio/guided-1186fe47335317.mp3"}, {"title": "Use one convention", "text": "The course uses a sine reference. Keep that reference when comparing phases. Do not mix a peak amplitude with an RMS phasor magnitude.", "audio": "audio/guided-6578105b6415fc.mp3"}], "check": {"question": "A sinusoid with a 10 V peak has an RMS value of…", "options": ["About 7.07 V", "10 V", "About 14.14 V"], "answer": 0, "why": "For a pure sinusoid, RMS = peak/√2."}}, "3.2": {"family": "phasor", "title": "Connect a sinusoid to its phasor", "steps": [{"title": "Start with the reference", "text": "Represent a fifty hertz sine wave using an RMS phasor. The ten volt peak in this example corresponds to about seven point zero seven volts RMS.", "audio": "audio/guided-006e3e2009ef9c.mp3"}, {"title": "Read the angle", "text": "The angle records phase relative to the chosen sine reference. Move the phase slider and watch the arrow rotate.", "audio": "audio/guided-d4e4aeeb294148.mp3"}, {"title": "Convert to rectangular form", "text": "The real component is the RMS magnitude times cosine of the angle. The imaginary component is the RMS magnitude times sine of the angle.", "audio": "audio/guided-f7e731a5360d1c.mp3"}, {"title": "Keep frequency common", "text": "Phasors compare steady-state sinusoids at the same frequency. Add phasors as complex quantities, not by adding only their magnitudes.", "audio": "audio/guided-0acba2d9d7d9f7.mp3"}], "check": {"question": "When adding two same-frequency phasors, add…", "options": ["Their complex components", "Only their magnitudes", "Their frequencies"], "answer": 0, "why": "Phasor addition is complex vector addition; relative phase matters."}}, "3.3": {"family": "ac-elements", "title": "Compare resistor, inductor, and capacitor", "steps": [{"title": "Use current as the reference", "text": "In a resistor, voltage and current have the same phase. Its impedance is the positive real resistance.", "audio": "audio/guided-21bbfdd07a98c7.mp3"}, {"title": "Look at an ideal inductor", "text": "Inductor impedance is positive j times inductive reactance. Its voltage leads current by ninety degrees.", "audio": "audio/guided-b736d76e4ed4f3.mp3"}, {"title": "Look at an ideal capacitor", "text": "Capacitor impedance is negative j times capacitive reactance. Its current leads voltage by ninety degrees.", "audio": "audio/guided-1496598c5f0662.mp3"}, {"title": "Check the signs", "text": "The imaginary sign determines the phase relationship. Use RMS voltage divided by impedance to obtain the current phasor, not just its magnitude.", "audio": "audio/guided-6566430e212b67.mp3"}], "check": {"question": "In an ideal capacitor, current…", "options": ["Leads voltage by 90°", "Lags voltage by 90°", "Is always in phase"], "answer": 0, "why": "ZC = −jXC. Dividing voltage by this impedance gives a current that leads voltage by 90°."}}, "3.4": {"family": "series-ac", "title": "Add impedances in series", "steps": [{"title": "Add the real and imaginary parts", "text": "The series circuit has thirty ohms of resistance, an adjustable inductive reactance, and twenty ohms of capacitive reactance.", "audio": "audio/guided-f49ad2bb19a3b0.mp3"}, {"title": "Find the net reactance", "text": "Subtract capacitive reactance from inductive reactance. A positive result is inductive; a negative result is capacitive.", "audio": "audio/guided-dcc00b043908f0.mp3"}, {"title": "Divide the RMS voltage by impedance", "text": "The supply is one hundred volts RMS. At the default reactances, impedance is thirty plus j forty ohms, its magnitude is fifty ohms, and current magnitude is two amperes.", "audio": "audio/guided-ae14e3a49089e1.mp3"}, {"title": "Predict the phase", "text": "For a positive impedance angle, current lags voltage. At zero net reactance, voltage and current are in phase. Move the reactance slider across this boundary.", "audio": "audio/guided-e60856a66714f5.mp3"}], "check": {"question": "At XL = XC in this series circuit, impedance is…", "options": ["Purely resistive", "Zero regardless of R", "Purely inductive"], "answer": 0, "why": "The imaginary parts cancel, leaving the nonzero resistance of 30 Ω."}}, "3.5": {"family": "parallel-ac", "title": "Add branch current phasors", "steps": [{"title": "Use the common voltage", "text": "A resistor and an ideal inductive reactance are connected in parallel across one hundred volts RMS. Both branches see the same voltage.", "audio": "audio/guided-2427618bee3d24.mp3"}, {"title": "Calculate each branch", "text": "The resistor branch current is voltage divided by resistance, in phase with voltage. The inductor branch current is ninety degrees behind voltage.", "audio": "audio/guided-568fb2fda8c66f.mp3"}, {"title": "Add the currents as vectors", "text": "The inductive reactance is twenty ohms, so its current magnitude is five amperes. At a twenty ohm resistance, the real current is also five amperes. Their sum has magnitude about seven point zero seven amperes.", "audio": "audio/guided-6778e09c4ebf9e.mp3"}, {"title": "Check the equivalent behavior", "text": "Do not add five and five to get ten amperes; the currents have different phases. Change the resistance to see the real component and total angle change.", "audio": "audio/guided-a66663fa58d37e.mp3"}], "check": {"question": "Two 5 A branch currents that differ by 90° sum to a magnitude of…", "options": ["About 7.07 A", "10 A", "0 A"], "answer": 0, "why": "The perpendicular components give √(5² + 5²) ≈ 7.07 A."}}, "3.6": {"family": "power", "title": "Build the AC power triangle", "steps": [{"title": "Start with RMS values", "text": "Our example uses one hundred volts RMS and two amperes RMS. Apparent power is their product: two hundred volt-amperes.", "audio": "audio/guided-ecb1e500e8a673.mp3"}, {"title": "Separate real and reactive power", "text": "Real power is apparent power times cosine of the voltage-current phase difference. Reactive power is apparent power times sine of that difference.", "audio": "audio/guided-56e9cd2b10a415.mp3"}, {"title": "Change the phase angle", "text": "The phase slider changes power factor. At zero angle, real power equals apparent power and reactive power is zero. At sixty degrees, real power is one hundred watts.", "audio": "audio/guided-bb51ee000488c6.mp3"}, {"title": "Check the triangle and units", "text": "Real power is measured in watts, reactive power in vars, and apparent power in volt-amperes. The squared apparent power equals squared real power plus squared reactive power.", "audio": "audio/guided-a3cfbfe7c5a065.mp3"}], "check": {"question": "For U = 100 V RMS, I = 2 A RMS, and φ = 60°, real power is…", "options": ["100 W", "200 W", "400 W"], "answer": 0, "why": "P = UI cosφ = 100 × 2 × 0.5 = 100 W."}}};
